    if !exists {
        return -1
    }

    lru.remove(node)
    lru.addFront(node)
    return node.value
}

func (lru *LRUCache) Put(key int, value int) {
    if lru.capacity == 0 {
        return
    }

    if node, exists := lru.nodes[key]; exists {
        node.value = value
        lru.remove(node)
        lru.addFront(node)
        return
    }

    if len(lru.nodes) == lru.capacity {
        oldest := lru.tail.prev
        lru.remove(oldest)
